import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { handle } from '@/server/api';

/** The Hyderabad 2027 plan model (generated by analysis/model.py + build_seed.py). Static, versioned with the code. */
export const GET = handle(async () => {
  const raw = await readFile(path.join(process.cwd(), 'data', 'plan.json'), 'utf8');
  return JSON.parse(raw);
});
